        - Ênfase na leitura: ${emphasis}
        - Carga emocional desejada: ${emotion}

        PERSONAGENS:
        1. Fenrir: Locutor de Drive. Rápido, animado, focado em vendas e energia.
        2. Sadaltager: Locutor Institucional. Voz de peito, elegante, rítmica e pausada.

        REGRAS DE FORMATAÇÃO:
        - Use reticências (...) para indicar pausas de respiração.
        - Use CAIXA ALTA para palavras que exigem ênfase ou aumento de volume.
        - O texto deve ser sempre um diálogo dinâmico entre os dois.
        - Título deve ser curto e impactante.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              lines: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    speaker: { type: Type.STRING, enum: ['Fenrir', 'Sadaltager'] },
                    text: { type: Type.STRING }
                  },
                  required: ["speaker", "text"]
                }
              }
            },
            required: ["title", "lines"]
          }
        }
      });

      const data = JSON.parse(response.text || '{}') as ScriptOutput;
      setScript(data);
      showSuccess("Roteiro gerado com sucesso!");
    } catch (err: any) {
      console.error(err);
      setError("Erro ao gerar roteiro. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const playScript = async () => {
    if (!script || playing) return;

    // Se já geramos o áudio antes, apenas reproduzimos
    if (generatedAudio) {
      setPlaying(true);
      const ctx = initAudioContext();
      const audioBuffer = await decodeAudioData(generatedAudio, ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setPlaying(false);
      source.start();
      return;
    }

    setPlaying(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const ttsPrompt = `TTS the following radio conversation:\n` + 
        script.lines.map(line => `${line.speaker}: ${line.text}`).join('\n');

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: ttsPrompt }] }],
        config: {
          responseModalities: ['AUDIO' as any],
          speechConfig: {
            multiSpeakerVoiceConfig: {
              speakerVoiceConfigs: [
                {
                  speaker: 'Fenrir',
                  voiceConfig: { prebuiltVoiceConfig: { voiceName: fenrirVoice } }
                },
                {
                  speaker: 'Sadaltager',
                  voiceConfig: { prebuiltVoiceConfig: { voiceName: sadaltagerVoice } }
                }
              ]
            }
          }
        }
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("Não foi possível gerar o áudio.");

      const pcmBytes = decode(base64Audio);
      setGeneratedAudio(pcmBytes);

      const ctx = initAudioContext();
      const audioBuffer = await decodeAudioData(pcmBytes, ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setPlaying(false);
      source.start();
    } catch (err: any) {
      setError("Erro na reprodução de áudio.");
      setPlaying(false);
    }
  };

  const downloadAudio = () => {
    if (!generatedAudio || !script) return;
    const blob = createWavBlob(generatedAudio, 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${script.title.replace(/\s+/g, '_')}_radio_spot.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showSuccess("Áudio exportado com sucesso!");
  };

  return (
    <div className="max-w-4xl mx-auto p-4 md:p-8">
      {/* Header */}
      <header className="flex flex-col md:flex-row justify-between items-center mb-10 gap-4">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 bg-indigo-600 rounded-full flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
            </svg>
          </div>
          <div>
            <h1 className="text-2xl font-bold tracking-tight text-white">Rádio Script Agent</h1>
            <p className="text-gray-400 text-sm">Produção Técnica Inteligente</p>
          </div>
        </div>

        <button 
          onClick={() => setShowSettings(!showSettings)}
          className={`px-4 py-2 rounded-lg border transition-all flex items-center gap-2 ${showSettings ? 'bg-gray-700 border-gray-600 text-white' : 'bg-transparent border-gray-700 text-gray-300 hover:border-gray-500'}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
          </svg>
          Configurações
        </button>
      </header>

      {/* Settings Panel */}
      {showSettings && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8 p-6 bg-gray-800/50 rounded-xl border border-gray-700 animate-in fade-in slide-in-from-top-4 duration-300">
          <div>
            <h3 className="text-sm font-semibold uppercase tracking-wider text-indigo-400 mb-4">Mapeamento de Vozes</h3>
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs text-gray-400 block">Voz para FENRIR (Drive)</label>
                <div className="flex gap-2">
                  <select 
                    value={fenrirVoice}
                    onChange={(e) => {
                      const v = e.target.value as VoiceName;
                      setFenrirVoice(v);
                      savePreference('fenrirVoice', v);
                    }}
                    className="flex-1 bg-gray-900 border border-gray-700 rounded-md px-3 py-1.5 text-sm focus:ring-1 focus:ring-indigo-500 outline-none text-white"
                  >
                    {AVAILABLE_VOICES.map(v => <option key={v.name} value={v.name}>{v.name} - {v.description}</option>)}
                  </select>
                  <button onClick={() => testVoice(fenrirVoice, 'Fenrir')} disabled={!!previewing} className="p-2 bg-gray-700 rounded-md hover:bg-gray-600 disabled:opacity-50 text-white">
                    {previewing === fenrirVoice ? '...' : '▶'}
                  </button>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-xs text-gray-400 block">Voz para SADALTAGER (Inst.)</label>
                <div className="flex gap-2">
                  <select 
                    value={sadaltagerVoice}
                    onChange={(e) => {
                      const v = e.target.value as VoiceName;
                      setSadaltagerVoice(v);
                      savePreference('sadaltagerVoice', v);
                    }}
                    className="flex-1 bg-gray-900 border border-gray-700 rounded-md px-3 py-1.5 text-sm focus:ring-1 focus:ring-indigo-500 outline-none text-white"
                  >
                    {AVAILABLE_VOICES.map(v => <option key={v.name} value={v.name}>{v.name} - {v.description}</option>)}
                  </select>
                  <button onClick={() => testVoice(sadaltagerVoice, 'Sadaltager')} disabled={!!previewing} className="p-2 bg-gray-700 rounded-md hover:bg-gray-600 disabled:opacity-50 text-white">
                    {previewing === sadaltagerVoice ? '...' : '▶'}
                  </button>
                </div>
              </div>
            </div>
          </div>

          <div>
            <h3 className="text-sm font-semibold uppercase tracking-wider text-indigo-400 mb-4">Produção Artística</h3>
            <div className="grid grid-cols-1 gap-4">
              <div className="space-y-2">
                <label className="text-xs text-gray-400 block">Tom Geral</label>
                <select value={tone} onChange={(e) => {setTone(e.target.value); savePreference('prodTone', e.target.value);}} className="w-full bg-gray-900 border border-gray-700 rounded-md px-3 py-1.5 text-sm text-white">
                  {TONES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-xs text-gray-400 block">Emoção Predominante</label>
                <select value={emotion} onChange={(e) => {setEmotion(e.target.value); savePreference('prodEmotion', e.target.value);}} className="w-full bg-gray-900 border border-gray-700 rounded-md px-3 py-1.5 text-sm text-white">
                  {EMOTIONS.map(e => <option key={e} value={e}>{e}</option>)}
                </select>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Main Form */}
      <section className="bg-gray-800 border border-gray-700 rounded-2xl p-6 shadow-2xl mb-8">
        <div className="space-y-4">
          <label className="block text-sm font-medium text-gray-300">Tema, Produto ou Campanha</label>
          <div className="flex flex-col md:flex-row gap-4">
            <input 
              type="text"
              value={theme}
              onChange={(e) => setTheme(e.target.value)}
              placeholder="Ex: Queima de Estoque de Verão na Loja X..."
              className="flex-1 bg-gray-900 border border-gray-700 rounded-xl px-4 py-3 text-lg focus:ring-2 focus:ring-indigo-500 outline-none transition-all placeholder:text-gray-600 text-white"
              onKeyDown={(e) => e.key === 'Enter' && generateScript()}
            />
            <button 
              onClick={generateScript}
              disabled={loading || !theme.trim()}
              className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 disabled:cursor-not-allowed rounded-xl font-bold transition-all shadow-lg shadow-indigo-600/20 active:scale-95 text-white"
            >
              {loading ? (
                <span className="flex items-center gap-2">
                  <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Processando...
                </span>
              ) : 'GERAR ROTEIRO'}
            </button>
          </div>
        </div>
      </section>

      {/* Error / Notification */}
      {error && (
        <div className="mb-6 p-4 bg-red-900/30 border border-red-800 text-red-200 rounded-xl animate-bounce">
          {error}
        </div>
      )}
      {notification && (
        <div className="fixed bottom-8 right-8 p-4 bg-green-600 text-white rounded-xl shadow-2xl animate-in fade-in slide-in-from-right-4 duration-300 z-50">
          {notification}
        </div>
      )}

      {/* Output Display */}
      {script && (
        <div className="animate-in fade-in slide-in-from-bottom-6 duration-500">
          <div className="bg-gray-800 border border-gray-700 rounded-2xl overflow-hidden shadow-2xl">
            <div className="p-6 border-b border-gray-700 flex flex-col sm:flex-row justify-between items-center bg-gray-800/80 backdrop-blur-sm sticky top-0 z-10 gap-4">
              <h2 className="text-xl font-bold text-indigo-300"># {script.title}</h2>
              <div className="flex gap-2">
                <button 
                  onClick={playScript}
                  disabled={playing}
                  className={`flex items-center gap-2 px-6 py-2 rounded-full font-bold transition-all ${playing ? 'bg-orange-500/20 text-orange-400 animate-pulse' : 'bg-green-600 hover:bg-green-500 text-white'}`}
                >
                  {playing ? (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                      </svg>
                      NO AR...
                    </>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
                      </svg>
                      {generatedAudio ? 'REPRODUZIR' : 'GERAR E OUVIR'}
                    </>
                  )}
                </button>

                {generatedAudio && (
                  <button 
                    onClick={downloadAudio}
                    className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-bold transition-all"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                    EXPORTAR
                  </button>
                )}
              </div>
            </div>

            <div className="p-8 space-y-8 bg-gray-900/30">
              {script.lines.map((line, idx) => (
                <div key={idx} className={`flex flex-col ${line.speaker === 'Sadaltager' ? 'items-end' : 'items-start'}`}>
                  <div className="flex items-center gap-2 mb-2">
                    <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded ${line.speaker === 'Fenrir' ? 'bg-indigo-600 text-white' : 'bg-gray-600 text-gray-200'}`}>
                      {line.speaker === 'Fenrir' ? 'Fenrir (Drive)' : 'Sadaltager (Inst)'}
                    </span>
                  </div>
                  <div className={`max-w-[85%] p-4 rounded-2xl text-lg leading-relaxed shadow-md ${
                    line.speaker === 'Fenrir' 
                      ? 'bg-indigo-900/40 border border-indigo-800/50 rounded-tl-none text-indigo-50' 
                      : 'bg-gray-800 border border-gray-700/50 rounded-tr-none text-gray-100 text-right'
                  }`}>
                    {line.text}
                  </div>
                </div>
              ))}
            </div>

            <div className="p-4 bg-gray-800/50 border-t border-gray-700 flex justify-center">
              <p className="text-xs text-gray-500 italic">Este roteiro foi otimizado para as características tímbricas de {fenrirVoice} e {sadaltagerVoice}.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export interface ScriptLine {
  speaker: 'Fenrir' | 'Sadaltager';
  text: string;
  direction?: string; // Instrução de atuação para o locutor
}

export interface ScriptOutput {
  title: string;
  bgm_suggestion: string; // Sugestão de trilha sonora
  sfx_hints: string[]; // Sugestões de efeitos sonoros
  lines: ScriptLine[];
}

export type VoiceName = 'Kore' | 'Puck' | 'Charon' | 'Fenrir' | 'Zephyr';

export const AVAILABLE_VOICES: { name: VoiceName; description: string }[] = [
  { name: 'Fenrir', description: 'Enérgico e Rápido (Ideal para Varejo)' },
  { name: 'Puck', description: 'Profundo e Elegante (Ideal para Institucional)' },
  { name: 'Kore', description: 'Alegre e Vibrante (Ideal para Promoções)' },
  { name: 'Zephyr', description: 'Suave e Natural (Ideal para Narração)' },
  { name: 'Charon', description: 'Sóbrio e Maduro (Ideal para Notícias)' },
];

export const NARRATIVE_STYLES = [
  { id: 'hard_sell', label: 'Hard Sell (Varejo Agressivo)', icon: '⚡' },
  { id: 'luxury', label: 'Premium / Luxo', icon: '💎' },
  { id: 'storytelling', label: 'Storytelling / Emocional', icon: '📖' },
  { id: 'cool', label: 'Moderno / Jovem', icon: '🎧' },
  { id: 'promo', label: 'Promoção de Sorteio', icon: '🎁' }
];

export const DURATIONS = [
  { label: '15 Segundos (Flash)', value: 15 },
  { label: '30 Segundos (Padrão)', value: 30 },
  { label: '60 Segundos (Testemunhal)', value: 60 }
];

export const TONES = ['Vendedor', 'Institucional', 'Informativo', 'Sensacionalista', 'Descontraído'];
export const EMPHASES = ['Velocidade Máxima', 'Pausas Dramáticas', 'Intensidade de Volume', 'Ritmo Musical'];
export const EMOTIONS = ['Empolgado', 'Sério', 'Confiante', 'Amigável', 'Urgente'];

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { 
  ScriptOutput, 
  VoiceName, 
  AVAILABLE_VOICES, 
  NARRATIVE_STYLES, 
  DURATIONS,
  TONES, 
  EMOTIONS 
} from './types';
import { decode, decodeAudioData, createWavBlob } from './services/audioUtils';

const App: React.FC = () => {
  const [theme, setTheme] = useState('');
  const [loading, setLoading] = useState(false);
  const [script, setScript] = useState<ScriptOutput | null>(null);
  const [playing, setPlaying] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notification, setNotification] = useState<string | null>(null);
  const [generatedAudio, setGeneratedAudio] = useState<Uint8Array | null>(null);

  // Customization States
  const [narrativeStyle, setNarrativeStyle] = useState(NARRATIVE_STYLES[0].id);
  const [intensity, setIntensity] = useState(70); // 0-100
  const [targetDuration, setTargetDuration] = useState(30);

  // Voice Settings
  const [fenrirVoice, setFenrirVoice] = useState<VoiceName>('Fenrir');
  const [sadaltagerVoice, setSadaltagerVoice] = useState<VoiceName>('Puck');

  const [showSettings, setShowSettings] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const savedFenrir = localStorage.getItem('fenrirVoice') as VoiceName;
    const savedSadaltager = localStorage.getItem('sadaltagerVoice') as VoiceName;
    if (savedFenrir) setFenrirVoice(savedFenrir);
    if (savedSadaltager) setSadaltagerVoice(savedSadaltager);
  }, []);

  const showSuccess = (msg: string) => {
    setNotification(msg);
    setTimeout(() => setNotification(null), 3000);
  };

  const initAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    return audioContextRef.current;
  };

  const generateScript = async () => {
    if (!theme.trim()) return;
    setLoading(true);
    setError(null);
    setScript(null);
    setGeneratedAudio(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const styleLabel = NARRATIVE_STYLES.find(s => s.id === narrativeStyle)?.label;

      const prompt = `Atue como um REDATOR DE RÁDIO FM PREMIADO. Crie um roteiro de marketing de alta conversão.
      TEMA: "${theme}"
      ESTILO DE CAMPANHA: ${styleLabel}
      INTENSIDADE DE VENDA: ${intensity}% (Onde 100% é agressividade máxima de varejo)
      TEMPO ESTIMADO: ${targetDuration} segundos.

      PERSONAGENS:
      1. FENRIR: Locutor de Drive. Personalidade: Elétrico, vendedor, "pra cima", usa gírias de rádio, cria senso de urgência.
      2. SADALTAGER: Locutor Institucional. Personalidade: Elegante, voz de autoridade, rítmico, traz a credibilidade final.

      REGRAS DE OURO DA REDAÇÃO:
      - Use GATILHOS MENTAIS (Escassez, Autoridade, Prova Social).
      - Use onomatopeias e pausas dramáticas (...).
      - FENRIR deve falar em CAIXA ALTA quando for para gritar ou enfatizar absurdamente.
      - SADALTAGER deve ser pontual e impactante.
      - Inclua instruções de "direction" para o TTS (ex: "com um sorriso na voz", "com urgência sussurrada").`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              bgm_suggestion: { type: Type.STRING },
              sfx_hints: { type: Type.ARRAY, items: { type: Type.STRING } },
              lines: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    speaker: { type: Type.STRING, enum: ['Fenrir', 'Sadaltager'] },
                    text: { type: Type.STRING },
                    direction: { type: Type.STRING, description: "Instrução de entonação para o motor de áudio" }
                  },
                  required: ["speaker", "text", "direction"]
                }
              }
            },
            required: ["title", "lines", "bgm_suggestion"]
          }
        }
      });

      const data = JSON.parse(response.text || '{}') as ScriptOutput;
      setScript(data);
      showSuccess("Roteiro Criativo Gerado!");
    } catch (err: any) {
      console.error(err);
      setError("Erro ao gerar roteiro criativo.");
    } finally {
      setLoading(false);
    }
  };

  const playScript = async () => {
    if (!script || playing) return;

    if (generatedAudio) {
      setPlaying(true);
      const ctx = initAudioContext();
      const audioBuffer = await decodeAudioData(generatedAudio, ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setPlaying(false);
      source.start();
      return;
    }

    setPlaying(true);
    setError(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Injetamos as instruções de direção diretamente no texto para o TTS
      const ttsPrompt = `Interpret this radio spot with maximum marketing energy:\n` + 
        script.lines.map(line => `${line.speaker}: (Say ${line.direction}) ${line.text}`).join('\n');

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: ttsPrompt }] }],
        config: {
          responseModalities: ['AUDIO' as any],
          speechConfig: {
            multiSpeakerVoiceConfig: {
              speakerVoiceConfigs: [
                {
                  speaker: 'Fenrir',
                  voiceConfig: { prebuiltVoiceConfig: { voiceName: fenrirVoice } }
                },
                {
                  speaker: 'Sadaltager',
                  voiceConfig: { prebuiltVoiceConfig: { voiceName: sadaltagerVoice } }
                }
              ]
            }
          }
        }
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("Falha na renderização do áudio.");

      const pcmBytes = decode(base64Audio);
      setGeneratedAudio(pcmBytes);

      const ctx = initAudioContext();
      const audioBuffer = await decodeAudioData(pcmBytes, ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setPlaying(false);
      source.start();
    } catch (err: any) {
      setError("Erro na interpretação de áudio.");
      setPlaying(false);
    }
  };

  const downloadAudio = () => {
    if (!generatedAudio || !script) return;
    const blob = createWavBlob(generatedAudio, 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `SPOT_${script.title.replace(/\s+/g, '_')}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showSuccess("Master exportada em WAV!");
  };

  return (
    <div className="max-w-5xl mx-auto p-4 md:p-8">
      {/* Header Profissional */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-6 border-b border-gray-800 pb-8">
        <div className="flex items-center gap-4">
          <div className="relative">
            <div className="w-16 h-16 bg-gradient-to-br from-indigo-600 to-purple-600 rounded-2xl flex items-center justify-center shadow-2xl shadow-indigo-500/20 rotate-3">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" />
              </svg>
            </div>
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-gray-900 animate-pulse"></div>
          </div>
          <div>
            <h1 className="text-3xl font-black tracking-tighter text-white uppercase italic">Studio Master <span className="text-indigo-500">FM</span></h1>
            <p className="text-gray-500 font-mono text-xs tracking-widest uppercase">Intelligent Radio Copywriting & Production</p>
          </div>
        </div>

        <div className="flex gap-2">
           <button 
            onClick={() => setShowSettings(!showSettings)}
            className={`px-4 py-2 rounded-xl border flex items-center gap-2 transition-all ${showSettings ? 'bg-gray-800 border-gray-600 text-white' : 'bg-transparent border-gray-800 text-gray-500 hover:border-gray-600'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37a1.724 1.724 0 002.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
            Setup
          </button>
        </div>
      </header>

      {/* Narrative DNA Console */}
      <section className="bg-gray-800/40 border border-gray-800 rounded-3xl p-6 mb-8 shadow-inner">
        <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-6 flex items-center gap-2">
          <span className="w-2 h-2 bg-indigo-500 rounded-full"></span>
          Narrative DNA & Marketing Engine
        </h3>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Style Selector */}
          <div className="space-y-3">
            <label className="text-xs font-bold text-gray-400 uppercase">Estilo de Campanha</label>
            <div className="grid grid-cols-1 gap-2">
              {NARRATIVE_STYLES.map(style => (
                <button
                  key={style.id}
                  onClick={() => setNarrativeStyle(style.id)}
                  className={`flex items-center gap-3 px-4 py-3 rounded-2xl border transition-all text-left ${narrativeStyle === style.id ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-600/20' : 'bg-gray-900/50 border-gray-800 text-gray-400 hover:border-gray-700'}`}
                >
                  <span className="text-xl">{style.icon}</span>
                  <span className="text-sm font-semibold">{style.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Intensity & Duration */}
          <div className="space-y-6">
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <label className="text-xs font-bold text-gray-400 uppercase">Intensidade de Venda</label>
                <span className="text-indigo-400 font-mono font-bold">{intensity}%</span>
              </div>
              <input 
                type="range" min="0" max="100" value={intensity} 
                onChange={(e) => setIntensity(parseInt(e.target.value))}
                className="w-full h-2 bg-gray-900 rounded-lg appearance-none cursor-pointer accent-indigo-500"
              />
              <div className="flex justify-between text-[10px] text-gray-600 font-bold uppercase tracking-tighter">
                <span>Sugestivo</span>
                <span>Equilibrado</span>
                <span>Agressivo</span>
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-bold text-gray-400 uppercase">Tempo de Spot</label>
              <select 
                value={targetDuration}
                onChange={(e) => setTargetDuration(parseInt(e.target.value))}
                className="w-full bg-gray-900 border border-gray-800 rounded-2xl px-4 py-3 text-sm text-white focus:ring-2 focus:ring-indigo-500 outline-none"
              >
                {DURATIONS.map(d => <option key={d.value} value={d.value}>{d.label}</option>)}
              </select>
            </div>
          </div>

          {/* Theme Input */}
          <div className="space-y-3 flex flex-col justify-between">
            <div className="space-y-3">
              <label className="text-xs font-bold text-gray-400 uppercase">Objeto da Campanha</label>
              <textarea 
                value={theme}
                onChange={(e) => setTheme(e.target.value)}
                placeholder="Ex: Liquidação de iPhones com 30% de desconto, só até amanhã na Loja do Centro."
                className="w-full bg-gray-900 border border-gray-800 rounded-2xl px-4 py-3 text-sm text-white h-32 focus:ring-2 focus:ring-indigo-500 outline-none resize-none placeholder:text-gray-700"
              />
            </div>
            <button 
              onClick={generateScript}
              disabled={loading || !theme.trim()}
              className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-800 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-indigo-600/20 active:scale-[0.98] transition-all flex items-center justify-center gap-3"
            >
              {loading ? (
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              ) : (
                <>
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                    <path d="M17.414 2.586a2 2 0 00-2.828 0L7 10.172V13h2.828l7.586-7.586a2 2 0 000-2.828z" />
                    <path fillRule="evenodd" d="M2 6a2 2 0 012-2h4a1 1 0 010 2H4v10h10v-4a1 1 0 112 0v4a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" clipRule="evenodd" />
                  </svg>
                  Redigir Campanha
                </>
              )}
            </button>
          </div>
        </div>
      </section>

      {/* Voice Settings Modal/Overlay */}
      {showSettings && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-gray-800 rounded-3xl p-8 max-w-2xl w-full shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-xl font-bold text-white uppercase tracking-tight">Voice Casting Setup</h2>
              <button onClick={() => setShowSettings(false)} className="text-gray-500 hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l18 18" />
                </svg>
              </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="space-y-4">
                <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block">Locutor FENRIR (Drive)</label>
                <select 
                  value={fenrirVoice}
                  onChange={(e) => setFenrirVoice(e.target.value as VoiceName)}
                  className="w-full bg-gray-800 border border-gray-700 rounded-2xl px-4 py-3 text-white outline-none"
                >
                  {AVAILABLE_VOICES.map(v => <option key={v.name} value={v.name}>{v.name} - {v.description}</option>)}
                </select>
              </div>
              <div className="space-y-4">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block">Locutor SADALTAGER (Inst.)</label>
                <select 
                  value={sadaltagerVoice}
                  onChange={(e) => setSadaltagerVoice(e.target.value as VoiceName)}
                  className="w-full bg-gray-800 border border-gray-700 rounded-2xl px-4 py-3 text-white outline-none"
                >
                  {AVAILABLE_VOICES.map(v => <option key={v.name} value={v.name}>{v.name} - {v.description}</option>)}
                </select>
              </div>
            </div>
            <button 
              onClick={() => setShowSettings(false)}
              className="w-full mt-10 py-4 bg-gray-800 hover:bg-gray-700 text-white rounded-2xl font-bold transition-all"
            >
              Salvar Configurações
            </button>
          </div>
        </div>
      )}

      {/* Roteiro e Playback */}
      {script && (
        <div className="animate-in fade-in slide-in-from-bottom-8 duration-700 pb-20">
          <div className="bg-gray-900 border border-indigo-900/30 rounded-3xl overflow-hidden shadow-2xl relative">

            {/* Playback Header */}
            <div className="p-6 bg-indigo-900/10 border-b border-gray-800 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="flex items-center gap-4">
                <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse shadow-[0_0_10px_rgba(220,38,38,0.8)]"></div>
                <h2 className="text-xl font-bold text-white tracking-tight">{script.title}</h2>
              </div>
              <div className="flex gap-3">
                <button 
                  onClick={playScript}
                  disabled={playing}
                  className={`flex items-center gap-3 px-8 py-3 rounded-full font-black transition-all ${playing ? 'bg-orange-600/20 text-orange-500 animate-pulse border border-orange-600/30' : 'bg-green-600 hover:bg-green-500 text-white shadow-xl shadow-green-600/20'}`}
                >
                  {playing ? (
                    <>
                      <div className="w-2 h-2 bg-orange-500 rounded-full animate-ping"></div>
                      AIRING...
                    </>
                  ) : (
                    <>
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
                      </svg>
                      {generatedAudio ? 'REPLAY MASTER' : 'RENDER MASTER'}
                    </>
                  )}
                </button>
                {generatedAudio && (
                  <button 
                    onClick={downloadAudio}
                    className="p-3 bg-gray-800 hover:bg-gray-700 text-indigo-400 rounded-full border border-gray-700 transition-all"
                    title="Baixar WAV"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                    </svg>
                  </button>
                )}
              </div>
            </div>

            {/* Production Notes */}
            <div className="px-8 py-4 bg-gray-800/30 border-b border-gray-800 grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="flex items-center gap-3">
                <span className="text-[10px] font-black text-gray-500 uppercase">Trilha Sugerida:</span>
                <span className="text-xs text-indigo-300 font-mono">{script.bgm_suggestion}</span>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-[10px] font-black text-gray-500 uppercase">Efeitos:</span>
                <div className="flex gap-2">
                  {script.sfx_hints.map((sfx, i) => (
                    <span key={i} className="text-[9px] bg-gray-800 px-2 py-0.5 rounded border border-gray-700 text-gray-400">[{sfx}]</span>
                  ))}
                </div>
              </div>
            </div>

            {/* Script Dialogue */}
            <div className="p-8 space-y-10">
              {script.lines.map((line, idx) => (
                <div key={idx} className={`flex flex-col ${line.speaker === 'Sadaltager' ? 'items-end' : 'items-start'}`}>
                  <div className={`flex items-center gap-3 mb-2 ${line.speaker === 'Sadaltager' ? 'flex-row-reverse' : ''}`}>
                    <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-lg ${line.speaker === 'Fenrir' ? 'bg-indigo-600 text-white' : 'bg-gray-700 text-gray-300'}`}>
                      {line.speaker === 'Fenrir' ? `LOC: ${fenrirVoice}` : `LOC: ${sadaltagerVoice}`}
                    </span>
                    <span className="text-[9px] font-mono text-gray-600 uppercase italic">({line.direction})</span>
                  </div>
                  <div className={`relative max-w-[80%] p-6 rounded-3xl text-xl leading-relaxed font-medium shadow-2xl ${
                    line.speaker === 'Fenrir' 
                      ? 'bg-gradient-to-br from-gray-800 to-gray-900 border border-indigo-500/20 rounded-tl-none text-white italic' 
                      : 'bg-gray-800 border border-gray-700 rounded-tr-none text-gray-200 text-right'
                  }`}>
                    {line.text}
                    {/* Decorative quote marks */}
                    <div className={`absolute -top-4 ${line.speaker === 'Fenrir' ? '-left-2' : '-right-2'} text-4xl text-white/5 font-serif`}>"</div>
                  </div>
                </div>
              ))}
            </div>

            <div className="p-6 bg-gray-950/50 border-t border-gray-800 text-center">
              <p className="text-[10px] text-gray-600 font-bold uppercase tracking-widest">
                Gerado via Studio Master FM Engine • {targetDuration}s Edit • {intensity}% Intensity
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Floating Errors */}
      {error && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 bg-red-600 text-white px-6 py-3 rounded-2xl shadow-2xl z-[200] animate-bounce">
          {error}
        </div>
      )}
    </div>
  );
};

export default App;
